1	//! Shared band-table renderer for tick-valued histograms.
2	//!
3	//! Both `TProbe` (fast path, direct-histogram) and `TProbeSpan`
4	//! (scope API, records → drain) store hardware tick deltas and
5	//! want the same band-table output shape — min/p1/…/p99/max
6	//! rows with first/last/range/count/mean columns, plus summary
7	//! lines for mean, stdev, mean min-p99, stdev min-p99. This
8	//! module provides a single implementation both can call into.
9	//!
10	//! Display unit is chosen by `as_ticks`: `false` converts stored
11	//! tick values to nanoseconds via [`crate::ticks::ticks_per_ns`];
12	//! `true` shows raw ticks.
13	
14	use hdrhistogram::Histogram;
15	
16	use crate::fmt::{fmt_commas, fmt_commas_f64};
17	use crate::ticks;
18	
19	const BOUNDARY_PCTS: &[f64] = &[
20	    0.0, 0.01, 0.10, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.80, 0.90, 0.99, 1.0,
21	];
22	const BOUNDARY_NAMES: &[&str] = &[
23	    "min", "p1", "p10", "p20", "p30", "p40", "p50", "p60", "p70", "p80", "p90", "p99", "max",
24	];
25	
26	/// Mean and stdev of the trimmed min-p99 band (samples whose
27	/// mid-rank falls below 0.99), in stored units — the values the
28	/// rendered report shows as `mean min-p99` / `stdev min-p99`.
29	/// `None` when the histogram is empty or every sample landed in
30	/// the top band.
31	pub(crate) fn trimmed_stats(hist: &Histogram<u64>) -> Option<(f64, f64)> {
32	    let sample_count = hist.len();
33	    if sample_count == 0 {
34	        return None;
35	    }
36	    let mut sum = 0u128;
37	    let mut cnt = 0u64;
38	    let mut cum = 0u64;
39	    for iv in hist.iter_recorded() {
40	        let value = iv.value_iterated_to();
41	        let count = iv.count_at_value();
42	        let mid_rank = (cum as f64 + count as f64 / 2.0) / sample_count as f64;
43	        if mid_rank < 0.99 {
44	            sum += value as u128 * count as u128;
45	            cnt += count;
46	        }
47	        cum += count;
48	    }
49	    if cnt == 0 {
50	        return None;
51	    }
52	    let mean = sum as f64 / cnt as f64;
53	    let mut var_sum = 0.0f64;
54	    let mut cum = 0u64;
55	    for iv in hist.iter_recorded() {
56	        let value = iv.value_iterated_to();
57	        let count = iv.count_at_value();
58	        let mid_rank = (cum as f64 + count as f64 / 2.0) / sample_count as f64;
59	        if mid_rank < 0.99 {
60	            let diff = value as f64 - mean;
61	            var_sum += diff * diff * count as f64;
62	        }
63	        cum += count;
64	    }
65	    let stdev = if cnt > 1 {
66	        (var_sum / cnt as f64).sqrt()
67	    } else {
68	        0.0
69	    };
70	    Some((mean, stdev))
71	}
72	
73	/// Display unit for a rendered band table.
74	#[derive(Clone, Copy, PartialEq, Eq)]
75	pub(crate) enum Unit {
76	    /// Convert stored ticks to nanoseconds (`ns`).
77	    Ns,
78	    /// Raw stored ticks (`tk`).
79	    Ticks,
80	    /// Unitless counts (`ct`) — no conversion.
81	    Count,
82	}
83	
84	/// Render a band-table report for `hist`. `kind` is the header
85	/// label (`"tprobe"`, `"tprobe-span"`, …) and `name` is the
86	/// probe's name. `unit` picks the display unit / conversion;
87	/// `decimals` is the fractional digits on every value column.
88	pub(crate) fn render(kind: &str, name: &str, hist: &Histogram<u64>, unit: Unit, decimals: usize) {
89	    let sample_count = hist.len();
90	    println!("  {kind}: {name} [count={}]", fmt_commas(sample_count));
91	    if sample_count == 0 {
92	        println!();
93	        return;
94	    }
95	
96	    let to_ns = unit == Unit::Ns;
97	    let unit = match unit {
98	        Unit::Ns => "ns",
99	        Unit::Ticks => "tk",
100	        Unit::Count => "ct",
101	    };
102	    let tpn = ticks::ticks_per_ns();
103	    let conv = |v: u64| -> f64 { if to_ns { v as f64 / tpn } else { v as f64 } };
104	    let conv_f = |v: f64| -> f64 { if to_ns { v / tpn } else { v } };
105	
106	    let n_bands = BOUNDARY_PCTS.len() - 1;
107	    let mut band_first = vec![u64::MAX; n_bands];
108	    let mut band_last = vec![0u64; n_bands];
109	    let mut band_count = vec![0u64; n_bands];
110	    let mut band_sum = vec![0u128; n_bands];
111	
112	    let mut cumulative = 0u64;
113	    for iv in hist.iter_recorded() {
114	        let value = iv.value_iterated_to();
115	        let count = iv.count_at_value();
116	        let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
117	        let idx = BOUNDARY_PCTS[1..]
118	            .iter()
119	            .position(|&b| mid_rank < b)
120	            .unwrap_or(n_bands - 1); // OK: rank ≥ last boundary → top band
121	        band_first[idx] = band_first[idx].min(value);
122	        band_last[idx] = band_last[idx].max(value);
123	        band_count[idx] += count;
124	        band_sum[idx] += value as u128 * count as u128;
125	        cumulative += count;
126	    }
127	
128	    struct BandRow {
129	        label: String,
130	        first: String,
131	        last: String,
132	        range: String,
133	        count: String,
134	        mean: String,
135	    }
136	
137	    let mut rows: Vec<BandRow> = Vec::new();
138	    for i in 0..n_bands {
139	        if band_count[i] == 0 {
140	            continue;
141	        }
142	        let mean_val = band_sum[i] as f64 / band_count[i] as f64;
143	        let range_raw = band_last[i] - band_first[i] + 1;
144	        rows.push(BandRow {
145	            label: format!("{}-{}", BOUNDARY_NAMES[i], BOUNDARY_NAMES[i + 1]),
146	            first: fmt_commas_f64(conv(band_first[i]), decimals),
147	            last: fmt_commas_f64(conv(band_last[i]), decimals),
148	            range: fmt_commas_f64(conv(range_raw), decimals),
149	            count: fmt_commas(band_count[i]),
150	            mean: fmt_commas_f64(conv_f(mean_val), decimals),
151	        });
152	    }
153	
154	    let label_w = rows
155	        .iter()
156	        .map(|r| r.label.len())
157	        .max()
158	        .unwrap_or(0) // OK: obvious
159	        .max("stdev min-p99".len());
160	    let first_w = rows.iter().map(|r| r.first.len()).max().unwrap_or(0); // OK: obvious
161	    let last_w = rows.iter().map(|r| r.last.len()).max().unwrap_or(0); // OK: obvious
162	    let range_w = rows.iter().map(|r| r.range.len()).max().unwrap_or(0); // OK: obvious
163	    let count_w = rows.iter().map(|r| r.count.len()).max().unwrap_or(0); // OK: obvious
164	    let mean_w = rows.iter().map(|r| r.mean.len()).max().unwrap_or(0); // OK: obvious
165	
166	    const INDENT: &str = "    ";
167	    const GAP: &str = "    ";
168	
169	    let first_col = INDENT.len() + label_w + 1 + first_w;
170	    let unit_len = 1 + unit.len();
171	    let last_gap = unit_len + GAP.len() + last_w;
172	    let range_gap = unit_len + GAP.len() + range_w;
173	    let count_gap = unit_len + GAP.len() + count_w;
174	    let mean_gap = GAP.len() + mean_w;
175	    println!(
176	        "{:>first_col$}{:>last_gap$}{:>range_gap$}{:>count_gap$}{:>mean_gap$}",
177	        "first", "last", "range", "count", "mean",
178	    );
179	
180	    for r in &rows {
181	        println!(
182	            "{INDENT}{:<label_w$} {:>first_w$} {unit}{GAP}{:>last_w$} {unit}{GAP}{:>range_w$} {unit}{GAP}{:>count_w$}{GAP}{:>mean_w$} {unit}",
183	            r.label, r.first, r.last, r.range, r.count, r.mean,
184	        );
185	    }
186	
187	    let hist_mean = hist.mean();
188	    let skip = first_w
189	        + unit_len
190	        + GAP.len()
191	        + last_w
192	        + unit_len
193	        + GAP.len()
194	        + range_w
195	        + unit_len
196	        + GAP.len()
197	        + count_w;
198	    println!(
199	        "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} {unit}",
200	        "mean",
201	        "",
202	        fmt_commas_f64(conv_f(hist_mean), decimals),
203	    );
204	    println!(
205	        "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} {unit}",
206	        "stdev",
207	        "",
208	        fmt_commas_f64(conv_f(hist.stdev()), decimals),
209	    );
210	
211	    if let Some((trim_mean, trim_stdev)) = trimmed_stats(hist) {
212	        println!(
213	            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} {unit}",
214	            "mean min-p99",
215	            "",
216	            fmt_commas_f64(conv_f(trim_mean), decimals),
217	        );
218	        println!(
219	            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} {unit}",
220	            "stdev min-p99",
