1	//! Span-based measurement probe: a named, single-writer
2	//! histogram plus a record buffer, populated via `start` /
3	//! `end` rather than `record(ticks)`.
4	//!
5	//! `start(site_id)` reads the hardware tick counter and returns
6	//! an opaque [`TProbeSpanId`] carrying `(site_id, start_tsc)`;
7	//! `end(id)` reads the tick counter again and appends a complete
8	//! `(site_id, start_tsc, end_tsc)` record to the probe's
9	//! internal buffer. No delta math, histogram ingestion, or
10	//! tick→ns conversion happens on the hot path — all of that is
11	//! deferred to [`TProbeSpan::report`], which drains pending records
12	//! into the histogram before rendering.
13	//!
14	//! This primitive preserves record-order information across
15	//! interleaved spans and sites (non-stack nesting is supported
16	//! by construction) and gives future evolution space for
17	//! per-site grouping, bounded buffers, background drain
18	//! threads, and long-term trace retention.
19	//!
20	//! The trade-off vs. [`crate::tprobe::TProbe`]: a growing
21	//! `Vec<Record>` in the hot path adds cache pressure and
22	//! reallocation cost in long, high-rate runs. For high-rate
23	//! single-histogram measurement prefer `TProbe`.
24	
25	use hdrhistogram::Histogram;
26	
27	use crate::band_table;
28	use crate::ticks;
29	
30	/// Opaque handle returned by [`TProbeSpan::start`], consumed by
31	/// [`TProbeSpan::end`]. Carries the caller-supplied `site_id` and
32	/// the start-time tick reading; no probe-internal allocation
33	/// happens at `start` time.
34	///
35	/// `#[must_use]` — dropping the id without passing it to
36	/// [`TProbeSpan::end`] leaks the span (no record is appended).
37	#[must_use]
38	#[derive(Clone, Copy, Debug)]
39	pub struct TProbeSpanId {
40	    site_id: u64,
41	    start_tsc: u64,
42	}
43	
44	/// A complete span record: `(site_id, start_tsc, end_tsc)`.
45	/// Appended at [`TProbeSpan::end`] time; the record buffer only
46	/// ever holds complete records. Drained into the histogram at
47	/// [`TProbeSpan::report`] time.
48	#[derive(Clone, Copy, Debug)]
49	struct Record {
50	    #[allow(dead_code)] // read once per-site grouping lands.
51	    site_id: u64,
52	    start_tsc: u64,
53	    end_tsc: u64,
54	}
55	
56	/// A named, single-writer histogram of hardware tick-counter
57	/// deltas plus a span-record buffer. Not `Sync`; cross-thread
58	/// *sharing* is out of scope. `Send` so probes can be moved
59	/// between threads (e.g. returned via a `JoinHandle<TProbeSpan>`
60	/// on shutdown).
61	pub struct TProbeSpan {
62	    name: String,
63	    hist: Histogram<u64>,
64	    records: Vec<Record>,
65	}
66	
67	impl TProbeSpan {
68	    /// Create an empty probe. Histogram upper bound is 1e12
69	    /// ticks (~250 s at 4 GHz, ~100 s at 10 GHz), 3 significant
70	    /// figures.
71	    ///
72	    /// Exits the process (code 1) if the hardware tick counter
73	    /// isn't usable — see [`crate::ticks::require_ok`].
74	    pub fn new(name: &str) -> Self {
75	        ticks::require_ok();
76	        let _ = ticks::ticks_per_ns();
77	        Self {
78	            name: name.to_string(),
79	            hist: Histogram::<u64>::new_with_bounds(1, 1_000_000_000_000, 3).unwrap(), // OK: constant bounds are valid
80	            records: Vec::new(),
81	        }
82	    }
83	
84	    /// Begin a span. Reads the hardware tick counter and
85	    /// returns an opaque [`TProbeSpanId`] carrying `(site_id,
86	    /// start_tsc)`. The id must eventually be passed to
87	    /// [`TProbeSpan::end`]; a dropped id leaves no record.
88	    #[inline]
89	    pub fn start(&mut self, site_id: u64) -> TProbeSpanId {
90	        TProbeSpanId {
91	            site_id,
92	            start_tsc: ticks::read_ticks(),
93	        }
94	    }
95	
96	    /// End the span started by [`TProbeSpan::start`]. Reads the
97	    /// hardware tick counter and appends a complete record
98	    /// `(site_id, start_tsc, end_tsc)` to the probe's record
99	    /// buffer. Delta and histogram ingestion are deferred to
100	    /// [`TProbeSpan::report`].
101	    #[inline]
102	    pub fn end(&mut self, tpri: TProbeSpanId) {
103	        let end_tsc = ticks::read_ticks();
104	        self.records.push(Record {
105	            site_id: tpri.site_id,
106	            start_tsc: tpri.start_tsc,
107	            end_tsc,
108	        });
109	    }
110	
111	    /// Render a band-table report for this probe. `as_ticks`
112	    /// controls the display unit: `false` converts stored tick
113	    /// deltas to nanoseconds (default for the CLI); `true` shows
114	    /// raw ticks (`-t`/`--ticks`). `decimals` is the fractional
115	    /// digits on every value column.
116	    ///
117	    /// Drains any pending `start`/`end` records into the histogram
118	    /// before rendering: `delta = end_tsc − start_tsc`, clamped to
119	    /// `1` since the histogram lower bound is 1.
120	    pub fn report(&mut self, as_ticks: bool, decimals: usize) {
121	        for r in self.records.drain(..) {
122	            let delta = r.end_tsc.saturating_sub(r.start_tsc);
123	            self.hist.record(delta.max(1)).unwrap(); // OK: clamped ≥1, and any real delta is under the 1e12 bound
124	        }
125	        let unit = if as_ticks {
126	            band_table::Unit::Ticks
127	        } else {
128	            band_table::Unit::Ns
129	        };
130	        band_table::render("tprobe-span", &self.name, &self.hist, unit, decimals);
131	    }
132	}
133	
134	#[cfg(test)]
135	mod tests {
136	    use super::*;
137	
138	    #[test]
139	    fn start_end_appends_one_record() {
140	        let mut p = TProbeSpan::new("t");
141	        let id = p.start(42);
142	        p.end(id);
143	        assert_eq!(p.records.len(), 1);
144	        let r = &p.records[0];
145	        assert_eq!(r.site_id, 42);
146	        assert!(r.end_tsc >= r.start_tsc);
147	    }
148	
149	    #[test]
150	    fn start_end_preserves_start_tsc() {
151	        let mut p = TProbeSpan::new("t");
152	        let id = p.start(7);
153	        let saved_start = id.start_tsc;
154	        p.end(id);
155	        let r = &p.records[0];
156	        assert_eq!(r.site_id, 7);
157	        assert_eq!(r.start_tsc, saved_start);
158	    }
159	
160	    #[test]
161	    fn start_end_interleaved_non_stack() {
162	        let mut p = TProbeSpan::new("t");
163	        let a = p.start(1);
164	        let b = p.start(2);
