            last: fmt_commas_f64(conv(band_last[i]), decimals),
            range: fmt_commas_f64(conv(range_raw), decimals),
            count: fmt_commas(band_count[i]),
            mean: fmt_commas_f64(conv_f(mean_val), decimals),
        });
    }

    let label_w = rows
        .iter()
        .map(|r| r.label.len())
        .max()
        .unwrap_or(0) // OK: obvious
